#include "netlib.h"
static int failed;
static volatile int http_done,dns_done;
static UiScene scene;
static char response[512];
static void check(int ok,const char *s){if(!ok){Log("NETWORK USER FAIL: ");Log(s);Log("\n");failed=1;Exit(1);}}
static int receive(int fd,void *data,u32 size){int r;u32 begin=Tick();while((r=recv(fd,data,size))==S_AGAIN&&Tick()-begin<400)Yield(1);return r;}
static int connected(int fd,u16 port){int r;u32 begin=Tick();while((r=connect(fd,port))==S_AGAIN&&Tick()-begin<400)Yield(1);return r;}
static int accepted(int fd){int r;u32 begin=Tick();while((r=accept(fd))==S_AGAIN&&Tick()-begin<400)Yield(1);return r;}
static void http_server(void){int server=socket(NET_TCP);check(server>0&&bind(server,8080)==0&&listen(server)==0,"HTTP listener");int peer=accepted(server);check(peer>0,"HTTP accept");char request[512];int n=receive(peer,request,sizeof(request));check(n>=16&&request[0]=='G'&&request[1]=='E'&&request[2]=='T',"HTTP request");const char *body="HTTP/1.0 200 OK\r\nContent-Length: 16\r\nConnection: close\r\n\r\nHello from SINO!";check(send(peer,body,strlen(body))==(int)strlen(body),"HTTP response");select_one(peer,2,100);Close(peer);Close(server);http_done=1;api(SYS_THREAD_EXIT,0,0,0);for(;;){}}
static void dns_server(void){int fd=socket(NET_UDP);check(fd>0&&bind(fd,53)==0,"DNS listener");u8 packet[512];SockAddress peer;int n;u32 begin=Tick();while((n=recvfrom(fd,packet,sizeof(packet),&peer))==S_AGAIN&&Tick()-begin<200)Yield(1);check(n>16&&n<480,"DNS query");packet[2]=0x81;packet[3]=0x80;packet[6]=0;packet[7]=1;const u8 answer[16]={0xc0,0x0c,0,1,0,1,0,0,0,60,0,4,127,0,0,1};memcpy(packet+n,answer,sizeof(answer));check(sendto(fd,packet,(u32)n+16,&peer)==n+16,"DNS reply");Close(fd);dns_done=1;api(SYS_THREAD_EXIT,0,0,0);for(;;){}}
int main(void){Log("NETWORK USER TEST BEGIN\n");u32 seq=(Tick()&32767)+1;u32 begin=Tick();int r;while((r=api(SYS_PING,NET_LOOPBACK,seq,0))==S_AGAIN&&Tick()-begin<100)Yield(1);check(r==0,"ICMP echo");Log("NETWORK ICMP LOOPBACK PASS\n");
 int a=socket(NET_UDP),b=socket(NET_UDP);check(a>0&&b>0&&bind(a,9000)==0&&bind(b,9001)==0&&connect(a,9001)==0&&connect(b,9000)==0,"UDP setup");check(send(a,"udp echo",8)==8,"UDP send");check(select_one(b,1,100)>0&&recv(b,response,3)==S_LIMIT&&recv(b,response,512)==8,"UDP datagram boundaries");check(send(b,response,8)==8&&receive(a,response,512)==8,"UDP echo");check(select_one(a,1,4)==S_AGAIN,"select timeout");Close(a);Close(b);Log("NETWORK UDP LOOPBACK/TIMEOUT/BOUNDS PASS\n");
 int server=socket(NET_TCP);check(server>0&&bind(server,9090)==0&&listen(server)==0,"TCP listen");a=socket(NET_TCP);check(connected(a,9090)==0,"TCP handshake");b=accepted(server);check(b>0,"TCP accept");check(send(a,"tcp echo",8)==8,"TCP send");check(receive(b,response,512)==8&&send(b,response,8)==8&&receive(a,response,512)==8,"TCP echo");check(send(a,response,513)==S_INVALID,"TCP MSS bound");Close(a);check(receive(b,response,512)==0,"TCP EOF");Close(b);Close(server);Log("NETWORK TCP HANDSHAKE/ECHO/FIN PASS\n");
 check(api(SYS_THREAD,(u32)dns_server,0,0)>0,"DNS thread");Yield(2);u32 ip=0;check(DnsResolve("sino.test",&ip)==0&&ip==NET_LOOPBACK,"DNS A response");while(!dns_done)Yield(1);Log("NETWORK DNS LOCAL QUERY PASS\n");
 check(api(SYS_THREAD,(u32)http_server,0,0)>0,"HTTP thread");Yield(2);r=HttpGet(8080,"/",response,sizeof(response));check(r>0&&response[0]=='H'&&response[9]=='2',"HTTP GET 200");while(!http_done)Yield(1);Log("NETWORK HTTP LOCAL GET PASS\n");
 a=socket(NET_TCP);begin=Tick();check(connected(a,6553)==S_IO&&Tick()-begin>=200,"connect timeout and retransmission");Close(a);NetStats stats;check(api(SYS_NET_INFO,(u32)&stats,0,0)==0&&stats.retransmits>=5&&stats.icmp_replies>0,"network statistics");
 Log("NETWORK USER TEST PASS\n");int w=Window("SINO 网络工具 / 回环验证",640,390);ui_begin(&scene);ui_text(&scene,24,57,"回环网络实测通过：127.0.0.1");ui_text(&scene,24,104,"ICMP echo / UDP echo / TCP 建连、传输、关闭");ui_text(&scene,24,144,"HTTP 本地 GET / 超时重传 / 缓冲边界");ui_text(&scene,24,190,"外部网卡、ARP、DHCP 与公网尚未启用。");ui_text(&scene,24,234,response);ui_button(&scene,24,320,130,"关闭");Scene(w,&scene);for(;;){UiEvent e;if(Event(&e)==0&&(ui_hit(&e,24,320,130,26)||(e.type==MSG_KEY&&e.key==27)))break;Yield(1);}return failed;}
